-- ============================================================================
-- B5 FOLLOW-ON W3 (Suite Full precision): crude capstone brief.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 2 and
-- the section 1 Suite rows, decision D3 (owner approved D1 to D7 as
-- recommended, 2026-09-21). The Suite app the capstone is read in gains a
-- "Full precision" switch, off by default, that prints the graded quantities
-- at the precision they are graded to. The brief now says to switch it on.
--
-- ADVANCED
--   Fields read with the switch on: onne_total_cost_usd, onne_fcc_volume_bbl,
--   onne_butane_volume_bbl, onne_sulfur_relief_usd_per_ppm,
--   onne_rvp_relief_usd_per_psi, onne_ron_relief_usd_per_octane.
--   The cards print cost to whole dollars, volumes to 1 decimal and shadow
--   prices to 2; the prompt asks 4.
--   APPENDED: Read the figures in the Product Blending Optimizer with its Full
--   precision switch on (at the top of the page): it prints them to the
--   precision this capstone grades, with no digit grouping.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance, and their order), title, dataset, status and the row. The guard
-- requires `fields` to equal its post-W1 value exactly, before and after, so
-- no answer grades differently and no attempts guard is needed.
--
-- ORDER. Apply only once the Suite build carrying the W3 switch is live (the
-- brief names it). Runs after W1 (20261024*): refuses without it.
--
-- GUARDS. Each prompt must hold its post-W1 text (md5, rewritten) or its W3
-- text (left alone), with the exact fields. Anything else raises and the file
-- rolls back. Generated by docs/graded-field-audit/w3_capstones.py from
-- w3/crude.json. SAFE TO RE-RUN: a second run writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_s0       text;
begin
  -- crude / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'crude' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w3 crude refused: crude/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '314ff1b59c141962fbfa0e066ab1e790' and fields = '[{"key": "onne_total_cost_usd", "tol": 0.00005, "unit": "dollars", "label": "Least total cost of the cargo", "expected": 872013.320248094}, {"key": "onne_fcc_volume_bbl", "tol": 0.00005, "unit": "bbl", "label": "FCC gasoline in the least-cost recipe", "expected": 3228.160923653412}, {"key": "onne_butane_volume_bbl", "tol": 0.00005, "unit": "bbl", "label": "Butane in the least-cost recipe", "expected": 437.0326736147707}, {"key": "onne_sulfur_relief_usd_per_ppm", "tol": 0.00005, "unit": "dollars per ppm", "label": "Value of relief on the sulfur limit, at the margin", "expected": 296.3096164435926}, {"key": "onne_rvp_relief_usd_per_psi", "tol": 0.00005, "unit": "dollars per psi", "label": "Value of relief on the RVP limit, at the margin", "expected": 6495.117849392539}, {"key": "onne_ron_relief_usd_per_octane", "tol": 0.00005, "unit": "dollars per octane number", "label": "Value of relief on the RON minimum, at the margin", "expected": 4032.630838167829}]'::jsonb then 'old'
              when md5(prompt) = 'd0dddfa16468f6b460f9a3b0b42736a5' and fields = '[{"key": "onne_total_cost_usd", "tol": 0.00005, "unit": "dollars", "label": "Least total cost of the cargo", "expected": 872013.320248094}, {"key": "onne_fcc_volume_bbl", "tol": 0.00005, "unit": "bbl", "label": "FCC gasoline in the least-cost recipe", "expected": 3228.160923653412}, {"key": "onne_butane_volume_bbl", "tol": 0.00005, "unit": "bbl", "label": "Butane in the least-cost recipe", "expected": 437.0326736147707}, {"key": "onne_sulfur_relief_usd_per_ppm", "tol": 0.00005, "unit": "dollars per ppm", "label": "Value of relief on the sulfur limit, at the margin", "expected": 296.3096164435926}, {"key": "onne_rvp_relief_usd_per_psi", "tol": 0.00005, "unit": "dollars per psi", "label": "Value of relief on the RVP limit, at the margin", "expected": 6495.117849392539}, {"key": "onne_ron_relief_usd_per_octane", "tol": 0.00005, "unit": "dollars per octane number", "label": "Value of relief on the RON minimum, at the margin", "expected": 4032.630838167829}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'crude' and tier = 'advanced' and active;
  if v_s0 = 'other' then
    raise exception 'w3 crude refused: crude/advanced matches neither its post-W1 form (prompt md5 314ff1b59c141962fbfa0e066ab1e790) nor its W3 form (prompt md5 d0dddfa16468f6b460f9a3b0b42736a5), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W3 form
  if v_s0 = 'new' then
    raise notice 'w3 crude: 0 of 1 row(s) written, all already applied';
    return;
  end if;

  -- W1 (20261024*) must be applied first: its rows are this file's base
  if not exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                  where c.app_slug = 'seismolord' and c.tier = 'intermediate' and c.active and f->>'key' = 'corr_zero_lag')
     or not exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                  where c.app_slug = 'mbal' and c.tier = 'beginner' and c.active and f->>'key' = 'eo_last_rb_stb')
     or not exists (select 1 from public.academy_capstones
                  where app_slug = 'basin' and tier = 'beginner' and active and prompt like 'Open book%') then
    raise exception 'w3 crude refused: W1 (20261024*) is not applied on this database; apply it first (/root/w1-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'ONNE BLENDING TERMINAL. A 10000 bbl PMS cargo is to be blended at least cost. Every figure is invented and illustrative. The components: Reformate: 95.3 dollars per bbl, SG 0.812 (density 0.812 kg/l), RON 99.2, MON 88.4, sulfur 3 ppm by mass, RVP 3.4 psi, up to 4600 bbl available. FCC gasoline: 86.2 dollars per bbl, SG 0.742 (density 0.742 kg/l), RON 91.6, MON 80.1, sulfur 140 ppm by mass, RVP 6.8 psi, up to 5000 bbl available. Light naphtha: 76.9 dollars per bbl, SG 0.668 (density 0.668 kg/l), RON 68.5, MON 66.2, sulfur 25 ppm by mass, RVP 11.8 psi, up to 3000 bbl available. Butane: 52.6 dollars per bbl, SG 0.584 (density 0.584 kg/l), RON 93.5, MON 89.6, sulfur 2 ppm by mass, RVP 51.5 psi, up to 650 bbl available. Alkylate: 91.5 dollars per bbl, SG 0.697 (density 0.697 kg/l), RON 95.8, MON 93.2, sulfur 4 ppm by mass, RVP 4.6 psi, tank typed as 0 bbl available. The buyer''s specification: RON at least 91 (blends on volume); MON at least 81 (blends on volume); Sulfur at most 50 ppm (blends on mass); RVP at most 9 psi (blends through the RVP index); Density between 0.72 and 0.775 kg/l (blends on volume). Give six numbers, each to four decimals. (1) The least total cost of the cargo, in dollars. (2) The barrels of FCC gasoline in the least-cost recipe. (3) The barrels of butane in it. (4) The value of relief on the sulfur limit at the least-cost recipe, as a shadow price: the cost saved per ppm the limit is relaxed, at the margin, in dollars per ppm. (5) The same for the RVP limit, in dollars per psi. (6) The same for the RON minimum, in dollars per octane number. Read the figures in the Product Blending Optimizer with its Full precision switch on (at the top of the page): it prints them to the precision this capstone grades, with no digit grouping.'
     where app_slug = 'crude' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w3 crude refused: crude/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'd0dddfa16468f6b460f9a3b0b42736a5' and fields = '[{"key": "onne_total_cost_usd", "tol": 0.00005, "unit": "dollars", "label": "Least total cost of the cargo", "expected": 872013.320248094}, {"key": "onne_fcc_volume_bbl", "tol": 0.00005, "unit": "bbl", "label": "FCC gasoline in the least-cost recipe", "expected": 3228.160923653412}, {"key": "onne_butane_volume_bbl", "tol": 0.00005, "unit": "bbl", "label": "Butane in the least-cost recipe", "expected": 437.0326736147707}, {"key": "onne_sulfur_relief_usd_per_ppm", "tol": 0.00005, "unit": "dollars per ppm", "label": "Value of relief on the sulfur limit, at the margin", "expected": 296.3096164435926}, {"key": "onne_rvp_relief_usd_per_psi", "tol": 0.00005, "unit": "dollars per psi", "label": "Value of relief on the RVP limit, at the margin", "expected": 6495.117849392539}, {"key": "onne_ron_relief_usd_per_octane", "tol": 0.00005, "unit": "dollars per octane number", "label": "Value of relief on the RON minimum, at the margin", "expected": 4032.630838167829}]'::jsonb) from public.academy_capstones where app_slug = 'crude' and tier = 'advanced' and active) is not true then
    raise exception 'w3 crude refused: crude/advanced does not read back as its W3 form';
  end if;

  raise notice 'w3 crude: % of 1 row(s) written, % already applied', v_written, 1 - v_written;
end $$;
